import type { Elements, RenderSurface } from 'claude-code'

type BandElements = Pick<Elements[RenderSurface], 'Box' | 'Button' | 'Text'>
export type BandState = { turnId: string; ordinal: number; files: number }

// The line above the prompt after a turn that changed code. Pure:
// register.tsx reads the state and hands over the handlers; no `onOpen`
// while the pane is already open.
export function bandView({ Box, Button, Text }: BandElements, band: BandState, onOpen: (() => void) | null, onHide: () => void) {
  return (
    <Box key="changes-band" flexDirection="row" gap={1}>
      <Text wrap="truncate-end">
        Turn #{band.ordinal} changed {band.files} {band.files === 1 ? 'file' : 'files'}
      </Text>
      {onOpen !== null ? <Button key="open" label="Open" onPress={onOpen} /> : null}
      <Button key="hide" label="Dismiss" onPress={onHide} />
    </Box>
  )
}

files.hooks/ui/notice.ts:
// The line the pane shows after a revert, in the spec's words (§5.4, §6).
// Pure: `turnName` turns a turn id into what the person sees ("#12").

import { REVERT_TURN } from '../core/model.ts'
import type { RevertOutcome } from '../io/restore.ts'

export function revertNotice(outcome: RevertOutcome, path: string, turnName: (turnId: string) => string): string {
  const side = (turnId: string) => (turnId === REVERT_TURN ? 'your earlier revert' : turnName(turnId))
  const turns = (ids: readonly string[]) => ids.map(turnName).join(', ')
  if (outcome.ok) return `Reverted ${path} (${turns(outcome.refs.map(r => r.turnId))}).`
  switch (outcome.reason) {
    case 'changed-since':
      return `${path} was also changed by ${turns(outcome.otherTurns)}. Revert those turns together, or none.`
    case 'user-changed-between':
      return `${path} was changed outside Claude between ${side(outcome.between[0])} and ${side(outcome.between[1])}. Reverting also undoes that change.`
    case 'history-trimmed':
      return `The history of ${path} between ${side(outcome.between[0])} and ${side(outcome.between[1])} was trimmed. Reverting also undoes what is no longer listed.`
    case 'unverifiable-link':
      return `Can't confirm nothing else changed ${path} between ${side(outcome.between[0])} and ${side(outcome.between[1])} (it may have been committed in between).`
    case 'changed-externally':
      return `${path} changed since Claude's last edit, so it was left alone.`
    case 'too-large':
      return `${path} is too large to restore (over 4 MiB, not clean in git before).`
    case 'no-snapshot':
      return `There is no saved copy of ${path} from before that turn.`
    case 'already-reverted':
      return `${path} was already reverted for that turn.`
    case 'nothing-to-revert':
      return `${path} has nothing to revert there.`
    case 'io':
      return `Reverting ${path} could not be confirmed: check the file before going on.`
  }
}

// A whole-turn revert, as planned at the first press or done at the second.
// `path` turns a file's path into what the pane shows.
export type TurnRevertSummary = {
  turn: string
  reverted: string[]
  // Each skipped file with why: a refusal's own words, or that it is kept.
  skipped: Array<{ path: string; why: RevertOutcome | 'kept' }>
  stopped: string | null
  notTried: number
}

export function revertAllNotice(s: TurnRevertSummary, turnName: (turnId: string) => string): string {
  const parts: string[] = []
  const files = (n: number) => `${n} ${n === 1 ? 'file' : 'files'}`
  parts.push(s.reverted.length > 0 ? `Reverted ${files(s.reverted.length)} of ${s.turn}.` : `Nothing in ${s.turn} was reverted.`)
  if (s.stopped !== null) {
    parts.push(`Stopped at ${s.stopped}: the write could not be confirmed, so ${files(s.notTried)} more ${s.notTried === 1 ? 'was' : 'were'} left alone. Check that file before going on.`)
  }
  if (s.skipped.length > 0) parts.push(`Skipped ${files(s.skipped.length)}: ${skippedWords(s.skipped, turnName)}`)
  return parts.join(' ')
}

// The first press: what the second will do, before anything is written.
export function revertAllPlanNotice(s: Pick<TurnRevertSummary, 'turn' | 'skipped'> & { writes: number }, turnName: (turnId: string) => string): string {
  if (s.writes === 0) return `Nothing in ${s.turn} can be reverted. ${skippedWords(s.skipped, turnName)}`
  return s.skipped.length === 0 ? '' : `Revert all skips ${s.skipped.length} of ${s.turn}'s files: ${skippedWords(s.skipped, turnName)}`
}

function skippedWords(skipped: TurnRevertSummary['skipped'], turnName: (turnId: string) => string): string {
  return skipped.map(({ path, why }) => (why === 'kept' ? `${path} is kept.` : revertNotice(why, path, turnName))).join(' ')
}

files.hooks/ui/pane.tsx:
import type { Elements, RenderSurface } from 'claude-code'

import { shownPath } from '../core/paths.ts'
import { turnTitle } from '../core/title.ts'
import type { FileChange, TimelineNode, TimelineRow } from '../core/timeline.ts'

type PaneElements = Pick<Elements[RenderSurface], 'Box' | 'Button' | 'Text' | 'Code'>

import type { DiffView } from '../io/diffs.ts'

export type RevertAsk = { turnId: string; key: string; path: string; mode: 'turn' | 'turnAndLater'; accept: boolean; label: string }

export type PaneInput = {
  rows: TimelineRow[]
  selected: string | null
  node: string | null
  // The selected turn's files, narrowed to `node` when one is selected.
  files: FileChange[]
  diffs: Record<string, DiffView>
  expanded: readonly string[]
  confirm: RevertAsk | null
  offer: RevertAsk | null
  // After Revert all: each skipped file's own way on, drawn on its row.
  offers: readonly RevertAsk[]
  // Revert all for the selected turn: offered while a file is pending, armed
  // after the first press.
  canRevertAll: boolean
  confirmAll: { turnId: string; label: string } | null
  notice: string | null
  // Why tracking is paused, when it is.
  paused: string | null
  cwd: string
  // When this launch began: rows from before it came from an earlier launch.
  launchedAt: number
  isWindows: boolean
  onSelect: (turnId: string) => void
  onNode: (node: string | null) => void
  onKeep: (file: FileChange) => void
  onRevert: (file: FileChange) => void
  onConfirm: (file: FileChange) => void
  onOffer: () => void
  onOfferFile: (ask: RevertAsk) => void
  onRevertAll: (turnId: string) => void
  onConfirmAll: (turnId: string) => void
  onShowAll: (file: FileChange) => void
}

const STATUS_MARK = { pending: '•', kept: '✓', reverted: '↶' } as const

// Element keys: register's ui.focus hook reads the `select-` and `node-`
// prefixes (selection only, never Keep, Revert or Confirm).
export const fileId = (file: Pick<FileChange, 'turnId' | 'key'>) => `${file.turnId}-${file.key}`

// The Changes pane: the timeline newest first; under the selected turn its
// steps (calls and agents) and its files, each with its diff, Keep and a
// two-step Revert. Pure: register.tsx computes the diffs and the handlers.
export function paneView({ Box, Button, Text, Code }: PaneElements, input: PaneInput) {
  const rows = input.rows.filter(r => r.kind === 'action' || r.files.length > 0 || r.untracked.length > 0)
  // Newest first: the first row from before this launch starts the earlier part.
  const firstEarlier = rows.findIndex(row => atOf(row) < input.launchedAt)
  const path = (p: string) => shownPath(input.cwd, p, input.isWindows)
  if (rows.length === 0) {
    return (
      <Box key="changes" flexDirection="column">
        {input.paused !== null ? <Text color="warning">{input.paused}</Text> : null}
        <Text dimColor>No changes yet. Each turn that edits files shows here, with its diffs.</Text>
      </Box>
    )
  }

  const nodeRows = (nodes: TimelineNode[], depth: number): ReturnType<typeof Button>[] =>
    nodes.flatMap(node => {
      const id = node.kind === 'call' ? node.toolUseId : node.agentId
      const name = node.kind === 'call' ? `${node.via === 'unattributed' ? 'changed during this turn (shell or you)' : node.tool}` : `agent ${node.label ?? node.agentId.slice(0, 8)}`
      const count = `${node.keys.length} ${node.keys.length === 1 ? 'file' : 'files'}`
      const isOn = input.node === id
      // Selecting sets, never toggles: a focus and a press arriving together
      // (the Desktop first click) must land on the same choice.
      const row = <Button key={`node-${id}`} plain label={`${'  '.repeat(depth + 2)}${isOn ? '●' : '○'} ${name} · ${count}`} onPress={() => input.onNode(id)} />
      return node.kind === 'agent' ? [row, ...nodeRows(node.children, depth + 1)] : [row]
    })

  const fileBlock = (file: FileChange) => {
    const id = fileId(file)
    const diff = input.diffs[file.key]
    const isConfirming = input.confirm !== null && input.confirm.turnId === file.turnId && input.confirm.key === file.key
    const counts = diff?.kind === 'diff' ? `  +${diff.added} −${diff.removed}` : ''
    const notes = [
      file.isNoop ? 'no net change' : null,
      diff?.kind === 'note' ? diff.text : null,
      diff?.kind === 'diff' && diff.eolOnly ? 'line endings only' : null,
      diff?.kind === 'diff' && diff.bomChanged ? 'byte-order mark changed' : null,
      diff?.kind === 'diff' && diff.capped ? 'too different to line up: shown as one replacement' : null,
      file.interleaved ? 'edited by two agents at once' : null,
      file.chainBroken ? 'changed outside Claude between edits; reverting this turn also undoes that' : null,
      file.edits.some(e => e.via === 'unattributed') ? 'changed during this turn (shell or you)' : null,
    ].filter((n): n is string => n !== null)
    const canAct = file.status !== 'reverted' && !file.isNoop
    const offer = input.offers.find(o => o.turnId === file.turnId && o.key === file.key)
    return (
      <Box key={`file-${id}`} flexDirection="column" marginBottom={1}>
        <Box key={`head-${id}`} flexDirection="row" gap={1}>
          <Text bold wrap="truncate-end">
            {STATUS_MARK[file.status]} {path(file.path)}
            {counts}
          </Text>
          {canAct ? <Button key={`keep-${id}`} label={file.status === 'kept' ? 'Undo keep' : 'Keep'} onPress={() => input.onKeep(file)} /> : null}
          {canAct && !isConfirming ? <Button key={`revert-${id}`} label="Revert" onPress={() => input.onRevert(file)} /> : null}
          {canAct && isConfirming ? <Button key={`confirm-${id}`} variant="primary" label={input.confirm!.label} onPress={() => input.onConfirm(file)} /> : null}
          {canAct && !isConfirming && offer !== undefined ? <Button key={`offer-${id}`} label={offer.label} onPress={() => input.onOfferFile(offer)} /> : null}
        </Box>
        {notes.map((note, i) => (
          <Text key={`note-${id}-${i}`} dimColor>
            {'  '}
            {note}
          </Text>
        ))}
        {diff?.kind === 'diff' && diff.hunks !== '' ? <Code source={diff.hunks} format="diff" path={file.path} /> : null}
        {diff?.kind === 'diff' && diff.shownRows < diff.totalRows ? (
          <Button key={`all-${id}`} plain label={`  … ${diff.totalRows - diff.shownRows} more lines · Show all`} onPress={() => input.onShowAll(file)} />
        ) : null}
      </Box>
    )
  }

  return (
    <Box key="changes" flexDirection="column">
      {input.paused !== null ? <Text color="warning">{input.paused}</Text> : null}
      {input.notice !== null ? (
        <Box key="notice" flexDirection="row" gap={1}>
          <Text wrap="wrap">{input.notice}</Text>
          {input.offer !== null ? <Button key="offer" label={input.offer.label} onPress={input.onOffer} /> : null}
        </Box>
      ) : null}
      {rows.flatMap((row, i) => (i === firstEarlier ? [earlierDivider(row), rowView(row)] : [rowView(row)]))}
    </Box>
  )

  function earlierDivider(row: TimelineRow) {
    return (
      <Text key="earlier" dimColor>
        ── Earlier · {whenOf(atOf(row))} ──
      </Text>
    )
  }

  function rowView(row: TimelineRow) {
        if (row.kind === 'action') {
          const verb = row.action.kind === 'revert' ? 'reverted' : row.action.kind === 'keep' ? 'kept' : 'unkept'
          return (
            <Text key={`action-${row.action.seq}`} dimColor>
              ↶ you {verb} {path(row.action.path)}
            </Text>
          )
        }
        const { turn, files, nodes, untracked } = row
        const isOpen = turn.turnId === input.selected
        const title = turn.kind === 'background' ? `background agent ${turn.turnId.slice('background:'.length, 'background:'.length + 8)}` : `#${turn.ordinal} ${turnTitle(turn.prompt)}`
        return (
          <Box key={`turn-${turn.turnId}`} flexDirection="column">
            <Button key={`select-${turn.turnId}`} plain label={`${isOpen ? '▾' : '▸'} ${title} · ${files.length} ${files.length === 1 ? 'file' : 'files'}`} onPress={() => input.onSelect(turn.turnId)} />
            {isOpen && turn.kind === 'turn' && input.confirmAll?.turnId === turn.turnId ? (
              <Button key={`confirmall-${turn.turnId}`} variant="primary" label={`    ${input.confirmAll.label}`} onPress={() => input.onConfirmAll(turn.turnId)} />
            ) : isOpen && turn.kind === 'turn' && input.canRevertAll ? (
              <Button key={`revertall-${turn.turnId}`} label={`    Revert all (#${turn.ordinal})`} onPress={() => input.onRevertAll(turn.turnId)} />
            ) : null}
            {isOpen && nodes.length > 1 ? (
              <Button key="node-all" plain label={`    ${input.node === null ? '●' : '○'} all steps`} onPress={() => input.onNode(null)} />
            ) : null}
            {isOpen && nodes.length > 1 ? nodeRows(nodes, 0) : null}
            {isOpen
              ? untracked.map(u => (
                  <Text key={`untracked-${u.seq}`} color="warning">
                    {'    '}⚠ {u.tool}: not tracked, {u.reason}
                  </Text>
                ))
              : null}
            {isOpen ? input.files.map(fileBlock) : null}
          </Box>
        )
  }
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

// "Oct 12, 14:05", in the time zone the mod runs in.
function whenOf(ms: number): string {
  const d = new Date(ms)
  const two = (n: number) => String(n).padStart(2, '0')
  return `${MONTHS[d.getMonth()]} ${d.getDate()}, ${two(d.getHours())}:${two(d.getMinutes())}`
}

function atOf(row: TimelineRow): number {
  return row.kind === 'action' ? row.action.at : row.turn.startedAt
}

files.hooks/core/diff.ts:
// Line diff for the Changes pane: Myers' O(ND) algorithm over interned lines,
// with the common prefix and suffix trimmed first and a cap on the edit
// distance, past which the changed middle becomes one replace hunk.
// Pure and synchronous; the output is the unified hunks a `Code` element
// draws under `format: 'diff'`.

export type Diff = {
  // Unified hunks only (`@@ -a,b +c,d @@` and their rows), joined by '\n';
  // '' when nothing but line endings or the BOM changed.
  hunks: string
  added: number
  removed: number
  // The texts differ only in line endings.
  eolOnly?: true
  // One text starts with a BOM and the other does not.
  bomChanged?: true
  // The edit distance passed the cap and the middle is one replace hunk.
  capped?: true
}

export type DiffOptions = {
  // Unchanged lines shown around each change; default 3.
  context?: number
  // Largest edit distance searched before falling back; default scales with
  // the trimmed size so one diff stays well inside a hook's budget.
  maxEditLength?: number
}

export type Eol = 'lf' | 'crlf' | 'mixed' | 'none'

const BOM = '﻿'
const NO_EOL = '\\ No newline at end of file'
const DEFAULT_CONTEXT = 3
const MAX_EDIT_LENGTH = 1000
const WORK_BUDGET = 20_000_000

export function eolOf(text: string): Eol {
  const crlf = text.match(/\r\n/g)?.length ?? 0
  const all = text.match(/\n/g)?.length ?? 0
  if (all === 0) return 'none'
  if (crlf === 0) return 'lf'
  return crlf === all ? 'crlf' : 'mixed'
}

export function diffText(before: string, after: string, options: DiffOptions = {}): Diff {
  const context = Math.max(0, options.context ?? DEFAULT_CONTEXT)
  const hasBomBefore = before.startsWith(BOM)
  const hasBomAfter = after.startsWith(BOM)
  const a = splitLines(hasBomBefore ? before.slice(1) : before)
  const b = splitLines(hasBomAfter ? after.slice(1) : after)

  // A last line with no final newline differs from the same text with one, so
  // it is interned apart: its own map, one id counter across both.
  const ids = new Map<string, number>()
  const noEolIds = new Map<string, number>()
  let nextId = 0
  const intern = (side: Side) =>
    Int32Array.from(side.lines, (line, i) => {
      const map = i === side.lines.length - 1 && !side.hasFinalNewline ? noEolIds : ids
      let id = map.get(line)
      if (id === undefined) map.set(line, (id = nextId++))
      return id
    })
  const aIds = intern(a)
  const bIds = intern(b)

  const { regions, capped } = changedRegions(aIds, bIds, options.maxEditLength)
  const { hunks, added, removed } = formatHunks(regions, a, b, context)

  const result: Diff = { hunks, added, removed }
  if (hunks === '' && withoutBom(before) !== withoutBom(after)) result.eolOnly = true
  if (hasBomBefore !== hasBomAfter) result.bomChanged = true
  if (capped) result.capped = true
  return result
}

type Side = { lines: string[]; hasFinalNewline: boolean }

// A change: lines [a0, a1) of before replaced by lines [b0, b1) of after.
type Region = { a0: number; a1: number; b0: number; b1: number }

function withoutBom(text: string): string {
  return text.startsWith(BOM) ? text.slice(1) : text
}

function splitLines(text: string): Side {
  if (text === '') return { lines: [], hasFinalNewline: true }
  const lines = text.split('\n')
  const hasFinalNewline = text.endsWith('\n')
  if (hasFinalNewline) lines.pop()
  return { lines: lines.map(line => (line.endsWith('\r') ? line.slice(0, -1) : line)), hasFinalNewline }
}

function changedRegions(a: Int32Array, b: Int32Array, maxEditLength?: number): { regions: Region[]; capped: boolean } {
  let start = 0
  while (start < a.length && start < b.length && a[start] === b[start]) start++
  let endA = a.length
  let endB = b.length
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA--
    endB--
  }

  const n = endA - start
  const m = endB - start
  if (n === 0 && m === 0) return { regions: [], capped: false }
  if (n === 0 || m === 0) return { regions: [{ a0: start, a1: endA, b0: start, b1: endB }], capped: false }

  const cap = maxEditLength ?? Math.max(1, Math.min(MAX_EDIT_LENGTH, Math.floor(WORK_BUDGET / (n + m))))
  const script = myers(a.subarray(start, endA), b.subarray(start, endB), cap)
  if (script === null) return { regions: [{ a0: start, a1: endA, b0: start, b1: endB }], capped: true }
  return {
    regions: script.map(r => ({ a0: r.a0 + start, a1: r.a1 + start, b0: r.b0 + start, b1: r.b1 + start })),
    capped: false,
  }
}

// Myers' greedy forward search, keeping each round's frontier for the
// backtrack. Returns the changed regions in order, or null past `max`.
function myers(a: Int32Array, b: Int32Array, max: number): Region[] | null {
  const n = a.length
  const m = b.length
  const limit = Math.min(max, n + m)
  const offset = limit + 1
  const v = new Int32Array(2 * limit + 3)
  // trace[d] holds the frontier for diagonals -(d-1)..(d-1) before round d.
  const trace: Int32Array[] = []

  for (let d = 0; d <= limit; d++) {
    trace.push(d === 0 ? new Int32Array(0) : v.slice(offset - (d - 1), offset + d))
    for (let k = -d; k <= d; k += 2) {
      let x = k === -d || (k !== d && v[offset + k - 1] < v[offset + k + 1]) ? v[offset + k + 1] : v[offset + k - 1] + 1
      let y = x - k
      while (x < n && y < m && a[x] === b[y]) {
        x++
        y++
      }
      v[offset + k] = x
      if (x >= n && y >= m) return backtrack(trace, d, n, m)
    }
  }
  return null
}

function backtrack(trace: Int32Array[], depth: number, n: number, m: number): Region[] {
  const deleted: number[] = []
  const inserted: number[] = []
  let x = n
  let y = m
  for (let d = depth; d > 0; d--) {
    const frontier = trace[d]
    const at = (k: number) => frontier[k + d - 1]
    const k = x - y
    const prevK = k === -d || (k !== d && at(k - 1) < at(k + 1)) ? k + 1 : k - 1
    const prevX = at(prevK)
    const prevY = prevX - prevK
    while (x > prevX && y > prevY) {
      x--
      y--
    }
    if (x === prevX) inserted.push(prevY)
    else deleted.push(prevX)
    x = prevX
    y = prevY
  }
  return regionsOf(deleted.reverse(), inserted.reverse(), n, m)
}

// Groups single-line deletions and insertions into regions: a region is a
// maximal run where the two sides advance without a matching line between.
function regionsOf(deleted: number[], inserted: number[], n: number, m: number): Region[] {
  const regions: Region[] = []
  let i = 0
  let j = 0
  let x = 0
  let y = 0
  while (i < deleted.length || j < inserted.length) {
    const nextDel = i < deleted.length ? deleted[i] : n
    const nextIns = j < inserted.length ? inserted[j] : m
    // Equal lines advance both sides until one of them reaches its next change.
    const skip = Math.min(nextDel - x, nextIns - y)
    x += skip
    y += skip
    const region = { a0: x, a1: x, b0: y, b1: y }
    while ((i < deleted.length && deleted[i] === region.a1) || (j < inserted.length && inserted[j] === region.b1)) {
      if (i < deleted.length && deleted[i] === region.a1) {
        region.a1++
        i++
      } else {
        region.b1++
        j++
      }
    }
    regions.push(region)
    x = region.a1
    y = region.b1
  }
  return regions
}

function formatHunks(regions: Region[], a: Side, b: Side, context: number): { hunks: string; added: number; removed: number } {
  const rows: string[] = []
  let added = 0
  let removed = 0
  const n = a.lines.length
  const m = b.lines.length
  const isLastOf = (side: Side, i: number) => i === side.lines.length - 1 && !side.hasFinalNewline

  let g = 0
  while (g < regions.length) {
    let h = g
    while (h + 1 < regions.length && regions[h + 1].a0 - regions[h].a1 <= 2 * context) h++
    const first = regions[g]
    const last = regions[h]
    const oldStart = Math.max(0, first.a0 - context)
    const oldEnd = Math.min(n, last.a1 + context)
    const newStart = first.b0 - (first.a0 - oldStart)
    const newEnd = last.b1 + (oldEnd - last.a1)
    const oldLen = oldEnd - oldStart
    const newLen = newEnd - newStart
    rows.push(`@@ -${oldLen === 0 ? oldStart : oldStart + 1},${oldLen} +${newLen === 0 ? newStart : newStart + 1},${newLen} @@`)

    const pushContext = (from: number, to: number) => {
      for (let i = from; i < to; i++) {
        rows.push(' ' + visible(a.lines[i]))
        if (isLastOf(a, i)) rows.push(NO_EOL)
      }
    }
    let at = oldStart
    for (let r = g; r <= h; r++) {
      const region = regions[r]
      pushContext(at, region.a0)
      for (let i = region.a0; i < region.a1; i++) {
        rows.push('-' + visible(a.lines[i]))
        if (isLastOf(a, i)) rows.push(NO_EOL)
      }
      for (let i = region.b0; i < region.b1; i++) {
        rows.push('+' + visible(b.lines[i]))
        if (isLastOf(b, i)) rows.push(NO_EOL)
      }
      removed += region.a1 - region.a0
      added += region.b1 - region.b0
      at = region.a1
    }
    pushContext(at, oldEnd)
    g = h + 1
  }
  return { hunks: rows.join('\n'), added, removed }
}

// At most `maxRows` rows of `hunks`, still drawable: whole hunks while they
// fit, and a first hunk longer than that cut with its header recounted
// (`Code` draws nothing of a hunk cut mid-way). `totalRows` counts every
// row but the headers; `shownRows` those kept.
export function limitHunks(hunks: string, maxRows: number): { hunks: string; shownRows: number; totalRows: number } {
  if (hunks === '') return { hunks, shownRows: 0, totalRows: 0 }
  const groups: string[][] = []
  for (const row of hunks.split('\n')) {
    if (row.startsWith('@@')) groups.push([row])
    else groups[groups.length - 1].push(row)
  }
  const bodyRows = (g: string[]) => g.length - 1
  const totalRows = groups.reduce((sum, g) => sum + bodyRows(g), 0)
  const kept: string[][] = []
  let shownRows = 0
  for (const group of groups) {
    if (shownRows + bodyRows(group) > maxRows) {
      if (kept.length === 0) {
        const cut = recount(group, maxRows)
        kept.push(cut)
        shownRows += bodyRows(cut)
      }
      break
    }
    kept.push(group)
    shownRows += bodyRows(group)
  }
  return { hunks: kept.map(g => g.join('\n')).join('\n'), shownRows, totalRows }
}

// The first `maxRows` rows of one hunk under a header that counts them.
function recount(group: string[], maxRows: number): string[] {
  const rows = group.slice(1, 1 + maxRows)
  const header = /^@@ -(\d+),(\d+) \+(\d+),(\d+) @@/.exec(group[0])
  const [oldStart, oldWas, newStart, newWas] = header ? header.slice(1).map(Number) : [1, 1, 1, 1]
  const oldLen = rows.filter(r => r[0] === ' ' || r[0] === '-').length
  const newLen = rows.filter(r => r[0] === ' ' || r[0] === '+').length
  // A side left with no rows names the line before it, as a header does.
  const start = (s: number, was: number, len: number) => (len === 0 && was > 0 ? s - 1 : s)
  return [`@@ -${start(oldStart, oldWas, oldLen)},${oldLen} +${start(newStart, newWas, newLen)},${newLen} @@`, ...rows]
}

// `Code` takes tab and newline as its only control characters; the rest are
// drawn as their Unicode control pictures (ESC as ␛, NUL as ␀, DEL as ␡).
function visible(line: string): string {
  return line.replace(/[\u0000-\u0008\u000a-\u001f\u007f]/g, c => (c === '\u007f' ? '␡' : String.fromCharCode(0x2400 + c.charCodeAt(0))))
}

